"""Loader for versioned local maintainer profiles; see README.md.

A profile is a line-oriented ``key = expression`` file. Blank lines and full-line ``#``
comments are ignored, each remaining line is split at its first ``=``, and the value is
evaluated as a Python expression. Non-``plugin`` entries land in ``settings``; ``plugin``
names the transform plugin to instantiate.

Values are evaluated by :class:`_RestrictedEvaluator`, not by :func:`eval`. The evaluator
walks the parsed AST against a strict allowlist of node types and only exposes pure
built-ins, so arithmetic, comprehensions, built-in calls and nested literals all work
while attribute access, dunder traversal, imports and file/process access are rejected.
Plugin names are resolved through the registry in ``plugins.py`` for the same reason: a
profile can select a plugin, but it cannot make this process import an arbitrary module.
"""

from __future__ import annotations

import ast
import importlib
import operator
from typing import Any, Iterator

from plugins import BUILTIN_PLUGINS, EXTERNAL_PLUGINS, known_plugins

PLUGIN_KEY = "plugin"

MAX_LINE_LENGTH = 4096
MAX_EVAL_STEPS = 1_000_000
MAX_POW_EXPONENT = 1024
MAX_SEQUENCE_ITEMS = 1_000_000
MAX_RANGE_LENGTH = 100_000


class ConfigError(ValueError):
    """Raised for a malformed profile line, a disallowed expression, or an unknown plugin."""


def _bounded_range(*args: Any) -> range:
    result = range(*args)
    if len(result) > MAX_RANGE_LENGTH:
        raise ConfigError(
            f"range() of {len(result)} items exceeds the limit of {MAX_RANGE_LENGTH}"
        )
    return result


def _bounded_pow(base: Any, exponent: Any, modulus: Any = None) -> Any:
    if isinstance(exponent, int) and not isinstance(exponent, bool):
        if abs(exponent) > MAX_POW_EXPONENT:
            raise ConfigError(
                f"exponent {exponent} exceeds the limit of {MAX_POW_EXPONENT}"
            )
    if modulus is None:
        return pow(base, exponent)
    return pow(base, exponent, modulus)


SAFE_BUILTINS: dict[str, Any] = {
    "abs": abs,
    "all": all,
    "any": any,
    "bool": bool,
    "dict": dict,
    "divmod": divmod,
    "enumerate": enumerate,
    "float": float,
    "frozenset": frozenset,
    "int": int,
    "len": len,
    "list": list,
    "max": max,
    "min": min,
    "pow": _bounded_pow,
    "range": _bounded_range,
    "reversed": reversed,
    "round": round,
    "set": set,
    "sorted": sorted,
    "str": str,
    "sum": sum,
    "tuple": tuple,
    "zip": zip,
}

_ALLOWED_LITERALS = frozenset({type(None), bool, int, float, complex, str, bytes})

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
}
_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Invert: operator.invert,
    ast.Not: operator.not_,
}
_CMP_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
    ast.In: lambda left, right: left in right,
    ast.NotIn: lambda left, right: left not in right,
}
_SEQUENCE_TYPES = (str, bytes, list, tuple)


class _RestrictedEvaluator:
    """Evaluates one parsed expression using an allowlist of AST node types."""

    def __init__(self) -> None:
        self._steps = 0

    def eval(self, tree: ast.Expression) -> Any:
        return self._eval(tree.body, dict(SAFE_BUILTINS))

    def _eval(self, node: ast.AST, env: dict[str, Any]) -> Any:
        self._steps += 1
        if self._steps > MAX_EVAL_STEPS:
            raise ConfigError(f"expression exceeded {MAX_EVAL_STEPS} evaluation steps")
        handler = _HANDLERS.get(type(node))
        if handler is None:
            raise ConfigError(f"{type(node).__name__} is not allowed in a profile expression")
        return handler(self, node, env)

    def _lookup(self, name: str, env: dict[str, Any]) -> Any:
        try:
            return env[name]
        except KeyError:
            raise ConfigError(f"name {name!r} is not available to profile expressions") from None

    def _constant(self, node: ast.Constant, env: dict[str, Any]) -> Any:
        if type(node.value) not in _ALLOWED_LITERALS:
            raise ConfigError(f"{type(node.value).__name__} literals are not allowed")
        return node.value

    def _name(self, node: ast.Name, env: dict[str, Any]) -> Any:
        if not isinstance(node.ctx, ast.Load):
            raise ConfigError("assignment is not allowed in a profile expression")
        return self._lookup(node.id, env)

    def _build_sequence(self, elts: list[ast.expr], env: dict[str, Any], factory: Any) -> Any:
        items: list[Any] = []
        for elt in elts:
            if isinstance(elt, ast.Starred):
                items.extend(self._eval(elt.value, env))
            else:
                items.append(self._eval(elt, env))
        return factory(items)

    def _list(self, node: ast.List, env: dict[str, Any]) -> Any:
        return self._build_sequence(node.elts, env, list)

    def _tuple(self, node: ast.Tuple, env: dict[str, Any]) -> Any:
        return self._build_sequence(node.elts, env, tuple)

    def _set(self, node: ast.Set, env: dict[str, Any]) -> Any:
        return self._build_sequence(node.elts, env, set)

    def _dict(self, node: ast.Dict, env: dict[str, Any]) -> Any:
        result: dict[Any, Any] = {}
        for key_node, value_node in zip(node.keys, node.values):
            if key_node is None:
                result.update(self._eval(value_node, env))
            else:
                result[self._eval(key_node, env)] = self._eval(value_node, env)
        return result

    def _unary_op(self, node: ast.UnaryOp, env: dict[str, Any]) -> Any:
        op = _UNARY_OPS.get(type(node.op))
        if op is None:
            raise ConfigError(f"operator {type(node.op).__name__} is not allowed")
        return op(self._eval(node.operand, env))

    @staticmethod
    def _check_repeat(left: Any, right: Any) -> None:
        if isinstance(left, _SEQUENCE_TYPES):
            sequence, count = left, right
        elif isinstance(right, _SEQUENCE_TYPES):
            sequence, count = right, left
        else:
            return
        if not isinstance(count, int) or isinstance(count, bool):
            return
        total = len(sequence) * abs(count)
        if total > MAX_SEQUENCE_ITEMS:
            raise ConfigError(
                f"repetition would build {total} items (limit {MAX_SEQUENCE_ITEMS})"
            )

    def _bin_op(self, node: ast.BinOp, env: dict[str, Any]) -> Any:
        if isinstance(node.op, ast.Pow):
            base = self._eval(node.left, env)
            exponent = self._eval(node.right, env)
            return _bounded_pow(base, exponent)
        op = _BIN_OPS.get(type(node.op))
        if op is None:
            raise ConfigError(f"operator {type(node.op).__name__} is not allowed")
        left = self._eval(node.left, env)
        right = self._eval(node.right, env)
        if isinstance(node.op, ast.Mult):
            self._check_repeat(left, right)
        return op(left, right)

    def _bool_op(self, node: ast.BoolOp, env: dict[str, Any]) -> Any:
        result: Any = True if isinstance(node.op, ast.And) else False
        for value_node in node.values:
            result = self._eval(value_node, env)
            if bool(result) is (not isinstance(node.op, ast.And)):
                return result
        return result

    def _compare(self, node: ast.Compare, env: dict[str, Any]) -> Any:
        left = self._eval(node.left, env)
        for op_node, comparator in zip(node.ops, node.comparators):
            op = _CMP_OPS.get(type(op_node))
            if op is None:
                raise ConfigError(f"comparison {type(op_node).__name__} is not allowed")
            right = self._eval(comparator, env)
            if not op(left, right):
                return False
            left = right
        return True

    def _if_exp(self, node: ast.IfExp, env: dict[str, Any]) -> Any:
        if self._eval(node.test, env):
            return self._eval(node.body, env)
        return self._eval(node.orelse, env)

    def _eval_index(self, node: ast.expr, env: dict[str, Any]) -> Any:
        if isinstance(node, ast.Slice):
            bounds = [
                None if bound is None else self._eval(bound, env)
                for bound in (node.lower, node.upper, node.step)
            ]
            return slice(*bounds)
        return self._eval(node, env)

    def _subscript(self, node: ast.Subscript, env: dict[str, Any]) -> Any:
        value = self._eval(node.value, env)
        index = self._eval_index(node.slice, env)
        try:
            return value[index]
        except (TypeError, KeyError, IndexError) as exc:
            raise ConfigError(f"bad subscript: {exc}") from None

    def _call(self, node: ast.Call, env: dict[str, Any]) -> Any:
        if not isinstance(node.func, ast.Name):
            raise ConfigError("only calls to allowlisted built-in functions are permitted")
        func = self._lookup(node.func.id, env)
        if not callable(func):
            raise ConfigError(f"{node.func.id!r} is not callable")
        args: list[Any] = []
        for arg in node.args:
            if isinstance(arg, ast.Starred):
                args.extend(self._eval(arg.value, env))
            else:
                args.append(self._eval(arg, env))
        kwargs: dict[str, Any] = {}
        for keyword in node.keywords:
            if keyword.arg is None:
                kwargs.update(self._eval(keyword.value, env))
            else:
                kwargs[keyword.arg] = self._eval(keyword.value, env)
        try:
            return func(*args, **kwargs)
        except ConfigError:
            raise
        except Exception as exc:
            raise ConfigError(f"{node.func.id}() failed: {exc}") from None

    def _bind(self, target: ast.expr, value: Any, scope: dict[str, Any]) -> None:
        if isinstance(target, ast.Name):
            scope[target.id] = value
            return
        if isinstance(target, (ast.Tuple, ast.List)):
            try:
                items = list(value)
            except TypeError:
                raise ConfigError("comprehension target is not unpackable") from None
            if len(items) != len(target.elts):
                raise ConfigError("comprehension target does not match its value")
            for elt, item in zip(target.elts, items):
                self._bind(elt, item, scope)
            return
        raise ConfigError(f"{type(target).__name__} is not allowed as a comprehension target")

    def _scopes(
        self, generators: list[ast.comprehension], env: dict[str, Any]
    ) -> Iterator[dict[str, Any]]:
        if not generators:
            yield env
            return
        generator = generators[0]
        if generator.is_async:
            raise ConfigError("async comprehensions are not allowed")
        iterable = self._eval(generator.iter, env)
        try:
            iterator = iter(iterable)
        except TypeError:
            raise ConfigError(f"{type(iterable).__name__} is not iterable") from None
        for item in iterator:
            scope = dict(env)
            self._bind(generator.target, item, scope)
            if all(self._eval(condition, scope) for condition in generator.ifs):
                yield from self._scopes(generators[1:], scope)

    def _list_comp(self, node: ast.ListComp, env: dict[str, Any]) -> Any:
        return [
            self._eval(node.elt, scope) for scope in self._scopes(node.generators, env)
        ]

    def _set_comp(self, node: ast.SetComp, env: dict[str, Any]) -> Any:
        return {self._eval(node.elt, scope) for scope in self._scopes(node.generators, env)}

    def _dict_comp(self, node: ast.DictComp, env: dict[str, Any]) -> Any:
        return {
            self._eval(node.key, scope): self._eval(node.value, scope)
            for scope in self._scopes(node.generators, env)
        }

    def _generator_exp(self, node: ast.GeneratorExp, env: dict[str, Any]) -> Any:
        return (self._eval(node.elt, scope) for scope in self._scopes(node.generators, env))


_HANDLERS = {
    ast.Constant: _RestrictedEvaluator._constant,
    ast.Name: _RestrictedEvaluator._name,
    ast.List: _RestrictedEvaluator._list,
    ast.Tuple: _RestrictedEvaluator._tuple,
    ast.Set: _RestrictedEvaluator._set,
    ast.Dict: _RestrictedEvaluator._dict,
    ast.UnaryOp: _RestrictedEvaluator._unary_op,
    ast.BinOp: _RestrictedEvaluator._bin_op,
    ast.BoolOp: _RestrictedEvaluator._bool_op,
    ast.Compare: _RestrictedEvaluator._compare,
    ast.IfExp: _RestrictedEvaluator._if_exp,
    ast.Subscript: _RestrictedEvaluator._subscript,
    ast.Call: _RestrictedEvaluator._call,
    ast.ListComp: _RestrictedEvaluator._list_comp,
    ast.SetComp: _RestrictedEvaluator._set_comp,
    ast.DictComp: _RestrictedEvaluator._dict_comp,
    ast.GeneratorExp: _RestrictedEvaluator._generator_exp,
}


def _evaluate(source: str, lineno: int) -> Any:
    """Evaluate one profile value expression, rejecting anything outside the allowlist."""
    try:
        tree = ast.parse(source, mode="eval")
    except SyntaxError as exc:
        raise ConfigError(f"line {lineno}: invalid expression: {exc.msg}") from None
    except (RecursionError, MemoryError, ValueError) as exc:
        raise ConfigError(f"line {lineno}: expression is too complex: {exc}") from None
    try:
        return _RestrictedEvaluator().eval(tree)
    except RecursionError as exc:
        raise ConfigError(f"line {lineno}: expression is nested too deeply") from None
    except ConfigError as exc:
        raise ConfigError(f"line {lineno}: {exc}") from None


def _load_plugin(value: Any) -> Any:
    """Instantiate the registered plugin named by ``value``, or return ``None`` if absent."""
    if value is None:
        return None
    if not isinstance(value, str) or not value:
        raise ConfigError(f"{PLUGIN_KEY} must be a non-empty plugin name, got {value!r}")
    if value in BUILTIN_PLUGINS:
        transform_cls = BUILTIN_PLUGINS[value]
    else:
        module_name = EXTERNAL_PLUGINS.get(value)
        if module_name is None:
            raise ConfigError(
                f"{PLUGIN_KEY} {value!r} is not registered in plugins.py; "
                f"known plugins: {', '.join(known_plugins())}"
            )
        module = importlib.import_module(module_name)
        transform_cls = getattr(module, "Transform", None)
        if transform_cls is None:
            raise ConfigError(f"plugin module {module_name!r} defines no Transform")
    return transform_cls()


def _parse_lines(text: str) -> Iterator[tuple[int, str, str]]:
    for lineno, raw_line in enumerate(text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if len(line) > MAX_LINE_LENGTH:
            raise ConfigError(f"line {lineno}: longer than {MAX_LINE_LENGTH} characters")
        key, separator, source = line.partition("=")
        if not separator:
            raise ConfigError(f"line {lineno}: expected 'key = expression', got {line!r}")
        key = key.strip()
        if not key.isidentifier():
            raise ConfigError(f"line {lineno}: invalid setting name {key!r}")
        yield lineno, key, source.strip()


def load_config(text: str) -> dict:
    """Parse profile ``text`` into ``{'settings': {...}, 'plugin': instance_or_None}``."""
    if not isinstance(text, str):
        raise TypeError(f"profile text must be a str, got {type(text).__name__}")
    settings: dict[str, Any] = {}
    plugin_name: Any = None
    for lineno, key, source in _parse_lines(text):
        value = _evaluate(source, lineno)
        if key == PLUGIN_KEY:
            plugin_name = value
        else:
            settings[key] = value
    return {"settings": settings, "plugin": _load_plugin(plugin_name)}
